 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # A solid row/column marks the boundaries between repeated compartments.
    lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            lines.append(('h', r, row[0]))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            lines.append(('v', c, vals[0]))

    # Use the orientation with the most complete separator lines.
    orient = 'h' if sum(x[0] == 'h' for x in lines) >= sum(x[0] == 'v' for x in lines) else 'v'
    cuts = sorted(x[1] for x in lines if x[0] == orient)
    if not cuts:
        return [row[:] for row in grid]
    size = h if orient == 'h' else w
    bounds = [-1] + cuts + [size]
    compartments = [(a + 1, b) for a, b in zip(bounds, bounds[1:]) if b > a + 1]
    if len(compartments) < 2:
        return [row[:] for row in grid]

    # Background is the most common color excluding separator lines.
    from collections import Counter
    sep_cells = set()
    for kind, pos, _ in lines:
        if kind == orient:
            if kind == 'h': sep_cells.update((pos, c) for c in range(w))
            else: sep_cells.update((r, pos) for r in range(h))
    counts = Counter(grid[r][c] for r in range(h) for c in range(w) if (r, c) not in sep_cells)
    bg = counts.most_common(1)[0][0]

    # Propagate all non-background marks by relative position in each compartment.
    out = [row[:] for row in grid]
    for idx in range(max(b-a for a, b in compartments)):
        marks = {}
        for a, b in compartments:
            if idx < b-a:
                for cross in range(w if orient == 'h' else h):
                    r, c = (a+idx, cross) if orient == 'h' else (cross, a+idx)
                    if grid[r][c] != bg:
                        marks[cross] = grid[r][c]
        for a, b in compartments:
            if idx < b-a:
                for cross, color in marks.items():
                    r, c = (a+idx, cross) if orient == 'h' else (cross, a+idx)
                    out[r][c] = color
    return out
